// The moment, its audio as a file for transcription, and the context the laptop sent (docs/CONTRACT.md, POST /turn).
// n8n keeps no state between turns: everything it decides from is here.
const b = $input.first().json.body;
const ctx = b.context || {};
const bundle = ctx.bundle || {};
const turns = ctx.turns || [];
const pitchEnd = turns.findIndex(t => t.mode === 'pitch_end');
const askedDuring = turns.filter((t, i) => (pitchEnd < 0 || i < pitchEnd) && t.mode !== 'pitch_end').reduce((a, t) => a + (t.reactions || []).filter(r => r.kind === 'question').length, 0);
const askedAfter = pitchEnd < 0 ? 0 : turns.slice(pitchEnd).reduce((a, t) => a + (t.reactions || []).filter(r => r.kind === 'question').length, 0);
const json = { session_id: b.session_id, mode: b.mode, slide_index: b.slide_index, t: b.t, asked_by: b.asked_by || '', mid_slide: !!b.mid_slide, time_up: !!b.time_up,
               bundle, elapsed: Math.round(ctx.elapsed_s || b.t || 0),
               turns, pending: ctx.pending || [], asked_during: askedDuring, asked_after: askedAfter };
// The laptop sends the speech as AAC (m4a), or WAV if it couldn't compress it
const audio = b.audio_base64 || b.audio_wav_base64 || '';
const m4a = b.audio_format === 'm4a';
return [{ json: { ...json, has_audio: !!audio }, binary: audio ? { audio: { data: audio, mimeType: m4a ? 'audio/mp4' : 'audio/wav', fileName: m4a ? 'turn.m4a' : 'turn.wav' } } : {} }];

// The prompt, kept short: a live turn should take a few seconds, and Groq's free tier allows 8,000 tokens a minute
const PROMPT = "You are the panel in a rehearsal of a real meeting, deciding how the room reacts to what the presenter just said.
React as these people would in this meeting: realistic, specific, never theatrical. During the pitch, most of the time nobody speaks.

The meeting: {meeting}
The plan for questions: {plan}. Asked so far: {asked_during} during the pitch, {asked_after} after it.
Time: {time}
The panel: {personas}
Lines voiced ahead of time (use one by its line_id when it fits, instead of new text): {lines}
The slide on screen: {slide}
What has happened so far, oldest first: {turns}
Questions raised but not answered yet: {pending}

This moment: {mode}{asked_by}
What the presenter just said: "{transcript}"

What to do for each moment:
- opening (their first words): if they introduced themselves or greeted the room, the chair welcomes them (kind "welcome", its line_id).
  If they went straight into the pitch, or said nothing, no reaction.
- segment (what they said on one slide): decide whether anyone interrupts now. Only someone whose manner is "interrupts", only while
  questions during the pitch remain in the plan (a guide: break it only for something that really matters), and only about this slide
  or what was just said: a claim with nothing behind it, a number that does not add up, a gap against their objections or the research.
  Never ask what the presenter already covered, and never repeat a pending question. A question: kind "question", raise_hand true,
  one or two sentences in that person's voice, referring to what was said. Otherwise no reaction. A segment sent mid-slide comes
  at one of the plan's interruption points (plan.interrupts): the hand there goes up only if that point still matters after what
  was said; if the presenter already answered it, nobody reacts.
- answer (to the question in this moment): judge it in answer_verdict: "resolved" (direct and specific), "partial" or "dodged". The person
  who asked reacts: an "acknowledge" line (by line_id) if resolved, or one "follow_up" (only if that question has had no follow-up yet)
  if partial or dodged and it matters. After the pitch, add what comes next: the next "question" from whoever matters most (a pending
  one first), or, once the questions in the plan are done or time is well past the pitch, the chair's "closing".
- pitch_end (the pitch is over): the chair opens the floor (kind "open_floor", its line_id), then the first "question" from whoever
  matters most, a pending one first. If the plan has no questions after the pitch, the chair closes instead. If the chair has just
  stopped the pitch for time, they have already moved to the questions: no open_floor, straight to the first question.
- closing (by the chair): how this kind of meeting really ends, in one or two sentences, fitting how it went (a next step if it went
  well, polite and noncommittal if not), and end_session true.
After the pitch, questions are asked directly (raise_hand false). Every reaction has a reason: one sentence on why this person said this
now, which the presenter reads afterwards. note: one short sentence to the presenter ("you") on how this moment landed, matching what
actually happens in reactions, also when nobody reacts (e.g. "You put a number on the savings, so Rajiv held his cost question.").
Spoken English, natural, short. Answer in JSON.";
const r = $('Read the turn').first().json;
const b = r.bundle;
const transcript = String(($json && $json.text) || '').trim();
const personas = (b.personas || []).map(p => ({ id: p.id, name: p.display_name, role: p.role, manner: p.manner, chair: p.chair, difficulty: p.difficulty,
  priorities: p.priorities, objections: (p.objections || []).map(o => (o.slide_index >= 0 ? 'slide ' + (o.slide_index + 1) + ': ' : '') + o.text) }));
const slide = (b.slides || []).find(s => s.index === r.slide_index);
const name = id => ((b.personas || []).find(p => p.id === id) || {}).display_name || id;
const history = r.turns.slice(-12).map(t => '[' + t.mode + (t.slide_index >= 0 ? ', slide ' + (t.slide_index + 1) : '') + '] presenter: "' + String(t.transcript || '').slice(0, 400) + '"'
  + (t.reactions || []).map(x => ' | ' + name(x.persona_id) + ' (' + x.kind + '): "' + x.text + '"').join('') + (t.answer_verdict ? ' | answer ' + t.answer_verdict : '')).join('
') || 'Nothing yet.';
const parts = {
  meeting: b.prospect && b.prospect.company ? 'with ' + b.prospect.company : 'a meeting', plan: JSON.stringify(b.plan || {}),
  asked_during: String(r.asked_during), asked_after: String(r.asked_after),
  // With a limit, how the chair keeps time; with none (time null, 0.25), the pitch length is only an estimate
  time: b.time && b.time.limit_s ? r.elapsed + ' seconds in, for a pitch of ' + b.time.limit_s + ' seconds' + (b.time.cut_at_s ? '; the chair stops the pitch at ' + b.time.cut_at_s + ' seconds' : '') + '.'
    : b.time === null ? r.elapsed + ' seconds in. No time limit (about ' + (b.pitch_seconds || 0) + ' seconds is only an estimate).'
    : r.elapsed + ' seconds in, for a pitch of ' + (b.pitch_seconds || 0) + ' seconds.',
  personas: JSON.stringify(personas), lines: JSON.stringify((b.lines || []).map(l => ({ line_id: l.id, persona_id: l.persona_id, kind: l.kind, text: l.text }))),
  slide: slide ? JSON.stringify({ number: slide.index + 1, title: slide.title, key_points: slide.key_points }) : 'No slides.',
  turns: history, pending: JSON.stringify(r.pending),
  mode: r.mode + (r.mid_slide ? " (mid-slide, at one of the plan's interruption points)" : '') + (r.time_up ? ' (the chair just stopped the pitch for time)' : ''), asked_by: r.asked_by ? ' (answering ' + name(r.asked_by) + ', id ' + r.asked_by + ')' : '', transcript,
};
// Each {name} in the prompt filled in by splitting, so nothing in the text is read as a replacement pattern
const prompt = Object.entries(parts).reduce((t, [k, v]) => t.split('{' + k + '}').join(v), PROMPT);
return [{ json: { ...r, transcript, prompt } }];

